def limpar(registros):
    limpos = []
    motivos = {}

    def marcar(motivo):
        motivos[motivo] = motivos.get(motivo, 0) + 1

    for registro in registros:
        sku = (registro.get("sku") or "").strip()
        if not sku:
            marcar("sku")
            continue
        try:
            valor = float(registro.get("valor"))
        except (TypeError, ValueError):
            marcar("valor")
            continue
        if valor < 0:
            marcar("negativo")
            continue
        limpos.append({"sku": sku, "valor": valor})

    return {
        "limpos": limpos,
        "descartados": sum(motivos.values()),
        "motivos": motivos,
    }

