def consolidar(resumo, lote):
    resultado = dict(resumo)

    vistos = set()
    totais_do_lote = {}

    for venda in lote:
        venda_id = venda.get("venda_id")
        if venda_id in vistos:
            continue
        vistos.add(venda_id)

        dia = venda["dia"]
        totais_do_lote[dia] = totais_do_lote.get(dia, 0) + venda["valor"]

    # Substituir, e nao somar ao que havia: e isso que torna a etapa repetivel.
    for dia, total in totais_do_lote.items():
        resultado[dia] = total

    return resultado

