exercise.solution:
def _chave(valor):
    return str(valor or "").strip().lower()


def juntar(vendas, produtos):
    por_sku = {}
    for produto in produtos:
        # setdefault: o primeiro cadastro vence e a linha nao se multiplica.
        por_sku.setdefault(_chave(produto.get("sku")), produto.get("nome"))

    linhas = []
    sem_cadastro = 0

    for venda in vendas:
        nome = por_sku.get(_chave(venda.get("sku")))
        if nome is None:
            sem_cadastro += 1
        linhas.append({"sku": venda.get("sku"), "valor": venda.get("valor"), "nome": nome})

    return {"linhas": linhas, "sem_cadastro": sem_cadastro}
